def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return max(0, bid)

    yesterday_bids = []
    desperate_count = 0
    failed_count = 0
    for opp in alive:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            yesterday_bids.append(pbid)
        status = prev.get('status')
        if status is not None and status != 'won_water':
            failed_count += 1

    player_count = len(alive) + 1
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < player_count

    if scarcity:
        base = DAILY_SALARY * 0.74
    else:
        base = DAILY_SALARY * 0.42

    if expected_units >= player_count + 1:
        base -= 8
    elif expected_units < max(1, player_count - 1):
        base += 8

    if yesterday_bids:
        top_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
        if top_prev >= DAILY_SALARY * 0.9:
            if hp >= 4 and no_water_days == 0:
                base = min(base, DAILY_SALARY * 0.33)
            else:
                base = max(base, DAILY_SALARY * 0.9)
        else:
            target = max(avg_prev + 2, top_prev + 1)
            if scarcity:
                base = max(base, target)
            else:
                base = max(base, min(target, DAILY_SALARY * 0.62))

    if desperate_count >= max(1, int(player_count / 2)):
        base += 5
    if failed_count >= max(1, int(len(alive) / 2)):
        base += 4

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.82)
    elif hp >= 8 and budget < DAILY_SALARY * 4:
        base = min(base, DAILY_SALARY * 0.45)

    if day >= 8:
        base += 4
    if budget <= DAILY_SALARY:
        base = min(base, budget)
    elif budget < DAILY_SALARY * 2 and hp > 4 and no_water_days == 0:
        base = min(base, DAILY_SALARY * 0.55)

    bid = max(0, min(budget, base))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid just enough to get water, or a small portion of salary
    if not alive_opponents:
        # If supply is less than my requirement, I can't get water anyway. Bid 0.
        if day_context['supply'] < WATER_REQ:
            return 0.0
        # Otherwise, bid conservatively to get water
        return min(float(my_status['budget']), DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid based on my HP and no_water_days
    current_bid = 0.0 

    # Emergency state: low HP or already missed water
    if my_status['no_water_days'] >= 1 or my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.95
    # High pressure state: HP is 3, need to secure water
    elif my_status['hp'] == 3:
        current_bid = DAILY_SALARY * 0.8
    # Normal state: moderate bid
    else:
        current_bid = DAILY_SALARY * 0.6

    # Adjust based on yesterday's highest opponent bid
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were very aggressive yesterday
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If I'm relatively safe, I can be slightly less aggressive
            if my_status['hp'] > 3:
                current_bid = max(current_bid, DAILY_SALARY * 0.7)
            # If I'm not safe, I must match/exceed
            else:
                current_bid = max(current_bid, highest_prev_bid + 5.0)
        # If opponents were moderately aggressive
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            current_bid = max(current_bid, highest_prev_bid + 2.0)
        # If opponents were conservative, maintain my current bid or slightly above them
        else:
            current_bid = max(current_bid, highest_prev_bid + 1.0)

    # Adjust based on current supply and number of competitors
    num_competitors = len(alive_opponents) + 1 # Myself + opponents
    supply = day_context['supply']

    # If supply is very low, competition will be fierce
    if supply < WATER_REQ * 1.5: # Not enough for two full requirements (13*1.5=19.5)
        current_bid = max(current_bid, DAILY_SALARY * 0.9)
    # If supply is tight (not enough for everyone to get their full requirement)
    elif supply < WATER_REQ * num_competitors:
        current_bid = max(current_bid, DAILY_SALARY * 0.75)

    # Ensure supply can actually satisfy my requirement
    if day_context['supply'] < WATER_REQ:
        return 0.0 # No point in bidding if supply is less than my requirement

    # Ensure bid is not negative and does not exceed budget
    final_bid = min(max(0.0, current_bid), float(my_status['budget']))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opps = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    high_prev = max(yesterday_bids) if yesterday_bids else 0
    hp = my_status['hp']
    budget = my_status['budget']
    if hp <= 2:
        # Need water desperately, bid up to almost full salary
        bid = min(budget, DAILY_SALARY * 0.95)
    elif hp <= 4:
        # Some need, but can be slightly conservative
        bid = min(budget, max(DAILY_SALARY * 0.65, high_prev + 1.5))
    else:
        # Healthy, try to save money
        bid = min(budget, max(DAILY_SALARY * 0.4, high_prev + 0.5))
    return max(0, min(bid, budget))
